    def genUniqueSuiteName(path: Os.Path, prefix: String): String = {
      var i = 0
      while(true) {
        val cand = path / s"${prefix}_${i}.scala"
        if (!cand.exists) {
          return s"${prefix}_${i}"
        }
        i = i + 1
      }
      halt("Infeasible")
    }

    for (p <- testCases) {
      art.Art.BridgeId.fromZ(p._1) match {
        case BeltQualificationOwner_acquisitionCoordinationProcess_beltQualificationOwner_id =>
          val prefix = "BeltQualificationOwner_acquisitionCoordinationProcess_beltQualificationOwner_RM_TestSuite"
          val path = testRoot /+ ISZ("scp_candidate","EIT_Acquisition_Session_Coordinator")
          val suiteName = genUniqueSuiteName(path, prefix)

          val testSuite =
            st"""package scp_candidate.EIT_Acquisition_Session_Coordinator
                |
                |import org.sireum._
                |import scp_candidate.EIT_Acquisition_Session_Coordinator._
                |
                |class ${suiteName} extends BeltQualificationOwner_acquisitionCoordinationProcess_beltQualificationOwner_ScalaTest {
                |  val verbose: B = T
                |
                |  ${p._2}
                |}"""
          val filename = path / s"${suiteName}.scala"
